INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure of Tokyo Disney Sea', 'In this game all the seven "ports of call" from the Tokyo DisneySea are represented: Mediterranean Harbor, American Waterfront, Lost River Delta, Port Discovery, Mermaid Lagoon, Arabian Coast, and Mysterious Island. The Aqua Sphere (symbol of the park) is also depicted. Disney''s characters include Aladdin and Ariel, among many others.
