INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Mickey Saves the Day: 3D Adventure', 'Mickey Saves the Day is an adventure game, with 3D characters against 2D-rendered backgrounds, for children. Players can choose to be Mickey or Minnie Mouse and many Disney characters make an appearance, such as Goofy, Donald and Daisy Duck, Pluto and Ludwig von Drake. The game is entirely mouse-controlled and the cursor changes when an object can be interacted with. It can either be used or picked up to be stored in an inventory, shown as Mickey''s hat at the bottom of the screen. Puzzles are solved by talking to other characters or through items. All visited locations are added to map to move around town.' FROM games WHERE igdb_id = 74101 ON CONFLICT (game_id, language_code) DO NOTHING;
