INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Piece: Tobidase Kaizoku-dan!', 'From TV Animation One Piece: Tobidase Kaizoku-dan! is a Japan-exclusive role-playing game created by Bandai for the PlayStation. It is the fourth game to be based on the One Piece manga and anime. This game''s introduction uses the theme song Believe from the One Piece Anime.' FROM games WHERE igdb_id = 75740 ON CONFLICT (game_id, language_code) DO NOTHING;
