INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galaxywars', 'Galaxywars was the first major German-language browser game, operated by Gameforge AG. It was a browser-based, massively multiplayer, online real-time strategy game set on a space environment. The game ran on any standard browser and was free.' FROM games WHERE igdb_id = 334423 ON CONFLICT (game_id, language_code) DO NOTHING;
