INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dib''s Nanochase', 'ZIM is piloting his microscopic spaceship through Dib''s body in order to reach his slimy, grey brain flesh and erase the knowledge that ZIM is an alien! Chase after him in your own tiny ship and blast his spindly alien husk out of Dib''s body!' FROM games WHERE igdb_id = 191879 ON CONFLICT (game_id, language_code) DO NOTHING;
