INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SakaTsuku Tokudaigou 2: J. League Pro Soccer Club wo Tsukurou!', 'SakaTsuku Tokudaigou 2: J. League Pro Soccer Club o Tsukurou! is a sports management simulation game with RPG elements released for the Sega Dreamcast on December 13, 2001. It is part of the long-running SEGA "Let''s Make a Pro Soccer Club!" series (also known as "Pro Soccer Club o Tsukurō!" or simply "SakaTsuku"). It serves as a direct sequel to J.League Pro Soccer Club o Tsukurou! (1999) and SakaTsuku Tokudaigou (2000).
