INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('disneys-doug-dougs-big-game', 49942, '2001-01-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4vte.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7i6i.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Doug: Doug''s Big Game', 'Doug makes his way to the videogame world with DOUG''S BIG GAME on Game Boy Color. You play Doug Funnie and his alter ego Quailman as you try to find your missing sweetheart, Patti Mayonnaise. You can also take on the role of your loyal pooch Porkchop, who also has own superhero alter ego: Quaildog. Solve the mystery of Patti''s disappearance by searching the town of Bluffington for clues and write in your journal so you can refer to them later. Discover who is behind Patti''s disappearance and her whereabouts by exploring 20 different environments from the popular TV show you''re bound to bump into more than a few of the show''s popular characters along the way. And don''t forget to keep an eye open for power-ups that will increase Quailman''s strength and powers. DOUG''S BIG GAME features detailed color graphics that bring the feel of the popular show right to the palm of your hand.' FROM games WHERE igdb_id = 49942 ON CONFLICT (game_id, language_code) DO NOTHING;
