INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nisemon-puzzle-da-mon', 282386, '2001-08-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7lyj.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nisemon: Puzzle da Mon!', 'The popular 4-panel manga serialized in "Comic BomBom" has become a game! The purpose is to rescue the companions trapped in the mysterious energy hall by Warmon. There are 3 characters that the player can take. Select a "character that can be used as a weapon" according to the situation, defeat the nasty "enemy character" on the stage, and rescue the "rescue character". Since the attack method, speed, and behavior change depending on the selected Nisemon, it is a real pleasure to freely use various strategies. You can also collect the characters that appear in the game as a picture book. Since the back information is also posted in the picture book, you can fully enjoy the charm of the Nisemon character.' FROM games WHERE igdb_id = 282386 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 282386 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
