INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek: Starfleet Command - Orion Pirates', 'Orion Pirates is a strategy game that involves thought and tactical maneuvers. Taking over command of one of the eight star empires from the original game you are able to choose between fighting against the Orion Pirates or joining forces with them to conquer the universe. During game play, players will control various ships and all of its systems while taking it into combat against enemy vessels.' FROM games WHERE igdb_id = 79758 ON CONFLICT (game_id, language_code) DO NOTHING;
