INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Charlie II', 'The sequel to the original Charlie the Duck. Every level is full of hidden and secret areas, and the challenge is to find them in order to collect coins and diamonds. Charlie can''t leave the level until he has found enough coins, which is determined by the difficulty setting. There are also hidden levels to unlock. There are 18 levels in this game, with only the first 6 levels playable in the shareware version. There is also an expansion pack that adds 18 additional levels to the registered version.' FROM games WHERE igdb_id = 72264 ON CONFLICT (game_id, language_code) DO NOTHING;
