INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Shot', 'Shooter Space Shot is a conventional flight shooter that offers a variety of weapons and equipment including missiles, boosters, and overdrives. Players must rack up impressive scores to earn the ability to save their progress but the game is designed to adjust itself on-the-fly to present a challenge matched to the player''s demonstrated skill level. Like many good traditional shooters, this release prides itself on offering enormous boss characters at the end of each level.' FROM games WHERE igdb_id = 44901 ON CONFLICT (game_id, language_code) DO NOTHING;
