INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Steppenwolf: The X-Creatures Project', 'Steppenwolf: The X-Creatures Project is a 2001 episodic action-adventure video game developed by Sarbakan and published by Warner Bros. Studios. The game centers around two characters, Meg Crimson and Alan "Steppenwolf" Kane, as they journey around the world in search of the blood samples of various cryptids rumored to have been alive for hundreds of years, all in an effort to finish the X-Creatures Project, an operation designed to grant humans immortality.
