INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The F.A. Premier League Stars 2001', 'Featuring the most exciting and challenging football league in the world, The F.A. Premier League Stars allows players to experience the fast paced action of the English Premier League right from the start of the 2000/2001 season. This GBC version based on the PC game features actual player names with all your favorite players from the F.A. Premier League (16 per team). The players exhibit differing levels of football skills as they do in real life. Controls allow for curling and chips with the help of aftertouch. Play quick matches or create and play in your own league of your favorite 2, 4, 6 or 8 teams for the EA Cup.' FROM games WHERE igdb_id = 50014 ON CONFLICT (game_id, language_code) DO NOTHING;
