INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jak & Daxter: The Lost Levels', 'The Lost Levels of Jak and Daxter was a java-based web browser game. The legend was that it was the original vision of the Jak and Daxter series, or at least The Precursor Legacy, developed by Gil Acheron in the 1990s and was previously unpublished.' FROM games WHERE igdb_id = 319202 ON CONFLICT (game_id, language_code) DO NOTHING;
