INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Bionicle', 'LEGO Bionicle is an action-adventure platformer in an isometric perspective. The player controls Takua, a villager on the island of Mata Nui through a series of linear levels that take place in the 6 different biomes across the island. This is the only canon handheld Bionicle game, and seems to serve as a prelude to the Mata Nui Online Game and Mata Nui Online Game II.' FROM games WHERE igdb_id = 6323 ON CONFLICT (game_id, language_code) DO NOTHING;
