INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Pooh''s Party Game: In Search of the Treasure', 'Winnie the Pooh''s Party Games: In Search of the Treasure is an adventure board game mixed with a compilation of exciting mini challenges that make it fun for a gathering of up to four friends. The game centers around a virtual board game that is simple fun and addicting. Each round starts a different mini-game and the results determine how each player advances on the main board.' FROM games WHERE igdb_id = 43724 ON CONFLICT (game_id, language_code) DO NOTHING;
