INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rocket-power-gettin-air', 8093, '2001-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa0n7.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocket Power: Gettin'' Air', 'They might be small, but that doesn''t mean they can''t enjoy extreme sports like the pros! The whole ROCKET POWER gang makes its way from the small screen adventures of their Nickelodeon program to the even smaller screen of the Game Boy Color. Such favorite characters as Otto, Reggie, Twister, and Sam are along for the adventure which, you can bet, will have plenty of extreme sports in it! There are 10 wild levels of action, which will have you snowboarding, surfing, skateboarding, and more. A comprehensive password system will help you pick up progress right where you left off, and the animation is lifted straight from the frames of the television program. If you perform well enough, you might even make the front page of Reggie''s Zine, a publication dedicated to the thrills of alternative sports. Packed with action, cutscenes, and tons of funny stuff, this is one thrill ride you''ll never want to get off of.' FROM games WHERE igdb_id = 8093 ON CONFLICT (game_id, language_code) DO NOTHING;
