INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zanac X Zanac', 'Zanac X Zanac is a shoot''em up game released by Compile to commemorate the 15th anniversairy of the original game. This title includes two games - a reimagination of the original game, called Zanac Neo and 3 different versions of the NES port of Zanac.' FROM games WHERE igdb_id = 46083 ON CONFLICT (game_id, language_code) DO NOTHING;
