INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mary-kate-ashley-crush-course', 5920, '2001-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/frk9doyofo3mxzt59v41.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mary-Kate & Ashley: Crush Course', 'Some totally cute boys have invited Mary-Kate and Ashley to a beach party but the directions have met a terrible fate! Someone has torn up the map that the twins were going to use to get to the shindig, and now they must pool their resources and find all of the pieces before the party starts without them. Some of the map is split up between the classrooms at school, some of them are in the hands of some weird girl that won''t give them back, and others have completely disappeared. There are tons of mini-games to keep young gamers busy here, including a mini-golf outing, a cheerleading challenge, and many others. One of the game''s best features is a creative music-making program that allows kids to punch in their own cool beats and tunes. You''ll start out the game in the freshman class, but piecing together the map and completing a few of the side games will earn you a pass to the higher grades. Get good marks and chase after good-looking boys in this fabulous adventure.' FROM games WHERE igdb_id = 5920 ON CONFLICT (game_id, language_code) DO NOTHING;
