INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rob Blanc III: The Temporal Terrorists', 'Something sinister is going on in the universe. Strange sightings have been reported; it seems that clones of ships, people and even planets have been appearing; clones that apparently echo both the future and the past. The governments of the universe have all drawn a blank - so they pass the buck onto Rob Blanc. Control both him and his sidekick Paul as you get to the bottom of the problem, visit four different interstellar locations and travel to a parallel universe...' FROM games WHERE igdb_id = 171553 ON CONFLICT (game_id, language_code) DO NOTHING;
