INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vault Assault', 'Vault Assault is a game based on the old arcade game Space Zap, written by Brian Prescott for the Atari 2600. Brian released Vault Assault in cartridge form at the 2001 Classic Gaming Expo, selling out all the copies he brought with him.' FROM games WHERE igdb_id = 40731 ON CONFLICT (game_id, language_code) DO NOTHING;
