INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('age-of-heroes-silkroad-2', 41110, '2001-03-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7vdx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/schzar.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Age of Heroes: Silkroad 2', 'The Age Of Heroes - Silkroad 2 is a 2D side-scrolling beat ''em-up game that puts players in the shoes of either the fighter Kai, assassin Shue, wizard Shenmue and warrior Chamuku. The adventure leads you along the Silkroad with a total of twenty-five different enemies. In a wartorn country a tournament was held to end the struggle between the various warring factions. The seven greatest fighters were awarded their own country. However Ba Wang the leader of the Yayool faction was unwilling to recognize the heroes'' reign. He subdued them and brought them under his control with a spell to do his bidding. It’s up to you to recover the souls of seven heroes from the evil Ba Wang.' FROM games WHERE igdb_id = 41110 ON CONFLICT (game_id, language_code) DO NOTHING;
