INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom and Jerry: Mouse Hunt', 'What is the world''s favorite cat-and-mouse duo up to these days? Well, just about the same thing they''ve been up to for the last 60-odd years fighting. Join all of your favorite friends from the long-running cartoon series for an experience that''s based entirely on the show.' FROM games WHERE igdb_id = 8031 ON CONFLICT (game_id, language_code) DO NOTHING;
