INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mia''s Math Adventure: Just in Time!', 'Mia''s Math Adventure: Just in Time! is the third title of the Mia''s Big Adventure Collection software series created by Kutoka Interactive. Released in 2001 in Canada and the United States, the game teaches mathematics to children between 6 and 10 years old.' FROM games WHERE igdb_id = 144378 ON CONFLICT (game_id, language_code) DO NOTHING;
