INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pao Lee Ming Kanshuu: Feng Shui Nyuumon', 'Pao Leeming Kanshuu - Fuusui Nyuumon is a simulation video game that is an introduction to Feng Shui, the game explains what is Feng Shui, the player will have diagnosis by each room (entrance, kitchen, bathroom, bedroom, etc.), by floor, items (like tv, furniture, etc.), also is each item is in harmony with the environment. There is also favorite diagnosis in which the game will provide a diagnosis in the directions of the player''s essenstial points. Also the Feng Shui by purpose in which it will provide the Feng Shui the is the right one about love, money, health, child care, work, etc.' FROM games WHERE igdb_id = 383234 ON CONFLICT (game_id, language_code) DO NOTHING;
