INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rasetsu', 'Rasetsu is a real time strategy with RPG elements that was released in 2001 for Microsoft Windows 98. It plays similarly to any other real-time strategy title with an isometric view and common point-and-click interface, and also toting somewhat of a Front Mission-esque as you''ll often find yourself switching over from battles to intermissions (where you''ll be able to talk to characters) and so on. The game features a techno soundtrack.' FROM games WHERE igdb_id = 93238 ON CONFLICT (game_id, language_code) DO NOTHING;
