INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castrol Honda World Superbike Team VTR', 'The only way to experience the latest in Superbike technology, Castrol Honda VTR gives you control of the Castrol Honda World Superbike teams VTR 1000. Almost 1000 ccs of power are yours to control over a range of tournaments spanning 22 international tracks. The game features the new VTR 1000 SP-1 and the new Castrol Honda World Superbike Team Livery. There are 23 computer opponents all with full animated riders so lets see if you can become the next Castrol Honda World Champion.' FROM games WHERE igdb_id = 278858 ON CONFLICT (game_id, language_code) DO NOTHING;
