INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NeoQuest', 'An HTML-based RPG Found on the Neopets Website. It''s a turn-based RPG where you move your way through the game one tile at a time, the page reloading each time you move a tile. You must adventure your way through the story in the game in the land of Neopia where you will be fighting evil, exploring dungeons, uncovering the story, and making valued allies and friends along the way. The game uses experience and skill points to power up the hero characters.' FROM games WHERE igdb_id = 229025 ON CONFLICT (game_id, language_code) DO NOTHING;
