INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rumble Racing', 'Rumble Racing is muscle car mayhem for the next millennium. Race outside the lines and push custom cars to the limit with big air stunts and nasty tricks as you race for the Rumble Championship. Unlock new worlds and new tracks with each Gold Cup victory, racing alone or partnering up with a friend.' FROM games WHERE igdb_id = 43280 ON CONFLICT (game_id, language_code) DO NOTHING;
