INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SCSIcide', 'SCSIcide is an original, fast-paced homebrew game released back in 2001 by Joe Grand of Pixels Past. In SCSIcide you play the role of a hard drive read head. As the different colored bits scroll by on the hard drive platter, you need to quickly read them in the correct order before you suffer a buffer underflow. As you complete each level, the data scrolls by more and more quickly! How far can you go? If you''re a fan of Activision''s Kaboom!, then you''ll love SCSIcide.' FROM games WHERE igdb_id = 70766 ON CONFLICT (game_id, language_code) DO NOTHING;
