INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phase Paradox', 'Phase Paradox is a survival-horror adventure game set aboard the damaged spacecraft GALLANT after the destruction of Planet 220. With many passengers dead or injured and strange phenomena occurring, players control three characters (Jude, Renee, and Alia) while trying to survive and escape the ship. Gameplay focuses on exploration and puzzle-solving in pre-rendered environments, with progression handled through interactive story events rather than direct combat or action sequences.' FROM games WHERE igdb_id = 43436 ON CONFLICT (game_id, language_code) DO NOTHING;
