INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Babies', '"Meet Buck, Meg and Derrick. They were normal everyday toddlers living at the Perfect Angels orphanage. That is, until a bolt of cosmic lightning crashed out of the sky. The radioactive DNA-altering bolt armed the toddlers with superhuman powers, turning them into the powerful force of the Mega Babies! Now, with the help of the nanny of all nannies, Nurse Lazlo, and her high tech cyber baby accessories, they are on a mission to obliterate evil."' FROM games WHERE igdb_id = 209532 ON CONFLICT (game_id, language_code) DO NOTHING;
