INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robot Wars: Metal Mayhem', 'Robot Wars: Metal Mayhem is the first video game based on the British game show Robot Wars. In the game, a competitor robot from the series, or a robot created by the player, is entered into combat against a robot controlled by the game. A bout finishes when one robot''s health bar is fully depleted.' FROM games WHERE igdb_id = 50022 ON CONFLICT (game_id, language_code) DO NOTHING;
