INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reversi', 'Reversi is based on the classic board game where your objective is to capture the most pieces on the game board by flipping discs to your color. A disc, or an unbroken line of discs of the same color, is captured when it becomes flanked on opposite ends by two opposing pieces, one of which must be the disc that was just placed on the board.' FROM games WHERE igdb_id = 88592 ON CONFLICT (game_id, language_code) DO NOTHING;
