INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Frog', 'When an army of plant-eating monsters invades the forest, only Super Frog can save the day! Run, jump and somersault from platform to platform as you rescue plants and send your enemies sailing over the treetops in enormous bubbles. Along the way, keep your eyes peeled for colorful candy bonuses and powerups to increase your energy and give you special powers. So what are you waiting for? Get off your lily pad and leap into adventure!' FROM games WHERE igdb_id = 80840 ON CONFLICT (game_id, language_code) DO NOTHING;
