INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Walking With Beasts: Operation Salvage', 'Walking with Beasts: Operation Salvage is a CD-ROM tie in to the series Walking with Beasts. It was only released in Europe. The game is set in 2027 where time travelers are sent to different times and places in prehistory by The World Wildlife Bionetwork. A female agent named Vega has defected to a rival organisation who is trying to capture the beasts. The player''s job is to find her, as well as destroy enemy equipment and free captured beasts.' FROM games WHERE igdb_id = 147898 ON CONFLICT (game_id, language_code) DO NOTHING;
