INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('zoboomafoo-playtime-in-zobooland', 49978, '2001-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1u6y.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zoboomafoo: Playtime in Zobooland', 'A talking lemur? The only place you might find such a thing is Zobooland, the magical place from the PBS series ZOBOOMAFOO. Embark on a nine-level quest to collect as many Animal Friend Cards as possible, a task that will require lots of interaction and cooperation with other creatures. Make your way across each side-scrolling level, trying to keep your energy up by eating Goobleberries. If you don''t eat enough, you''ll run out of energy and fall asleep losing one turn. Collecting 100 Goobleberries will earn you an extra shot at completing the game, but that won''t be easy with so many other tasks to keep your mind on. The game is certainly designed for younger players, but three skill settings (easy, easier, easiest) allow the game''s difficulty to expand as kids grow accustomed to the challenges. Though the journey is long, games can be saved with the use of a password.' FROM games WHERE igdb_id = 49978 ON CONFLICT (game_id, language_code) DO NOTHING;
