INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beauty or the Beast', 'Beauty or The Beast allows the player to adventure through a variation of the classic "Beauty and the Beast" tale through the eyes of either the Beauty or the Beast. From the perspective of Belle (the Beauty), her father has been imprisoned in the Beast''s castle and she must find her way through the castle in order to rescue him. The Beast is investigating interlopers in his domain.
