INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alienators: Evolution Continues', 'You thought you''d rid the Earth of the aliens. But now they''re back, and the evolution of hostile life-forms continues. Lucky for Earth, the Alienators are on the job. Use all the alien-butt-kicking science within your grasp to battle the Genus... before this evil evolves to a state of total supremacy and succeeds in global domination!' FROM games WHERE igdb_id = 49166 ON CONFLICT (game_id, language_code) DO NOTHING;
