INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtua Striker 3', 'The Virtua Striker series returns with 32 national soccer teams from around the world. Whether you play as France, Brazil or Argentina, you can lead your team to the International Cup final for a chance to win the trophy. On the way to the International Cup, you will meet more than 1,400 different players with their own statistics and you will play in 13 stadiums.' FROM games WHERE igdb_id = 39789 ON CONFLICT (game_id, language_code) DO NOTHING;
