INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shaun Palmer''s Pro Snowboarder', 'Shaun Palmer''s Pro Snowboarder is real life racing and freestyle snowboarding featuring living legend and six-time Winter X-Games gold medallist Shaun Palmer and 9 of the most bad ass names in the sport. Players race down the slopes of real world locations pulling hundreds of authentic trick combos. The game has expansive interactive environments allowing players to not only explore hidden and secret areas but stick tricks off anything in sight. Immediately playable yet challenging, it is a competitive, authentic and aggressive snowboarding game that will keep even the most hardcore Snowboarders and gamers hyped.' FROM games WHERE igdb_id = 3995 ON CONFLICT (game_id, language_code) DO NOTHING;
