INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pooh''s Party Game: In Search of the Treasure', 'Join Winnie the Pooh an exciting adventure in search of lost treasure! Invite your friends to join the fun--play lots of games with each other (and play silly tricks ON each other!). A good time is sure to be had by all--just remember to watch out for Woozles and Heffalumps!' FROM games WHERE igdb_id = 44745 ON CONFLICT (game_id, language_code) DO NOTHING;
