INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('venture-ii', 46889, '2001-08-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5yn1.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Venture II', 'Venture II was created by Tim Snider as a sequel to the classic game Venture. Only 24 copies of Venture II were produced. The first four carts were part of a pre-production run so Tim could get the manufacturing process fine tuned. Those first four are marked with Greek letters on the label. Tim then created 20 numbered copies of Venture II which he made available privately at the 2001 Classic Gaming Expo. One copy of Venture II sold at the CGE2K1 auction and went for over $200. Tim created perhaps the most extravagant packaging seen for a self-published title at the time--the game was delivered in a hand-crafted, miniature treasure chest, which opened to reveal the cartridge (with numbered label) and a manual, surrounded by elegant, gold leaf paper.
