INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kabuki Warriors', 'As a fight promoter for a troop of Kabuki warriors trying to travel from Edo to Kyoto, your actor/samurai must possess both strength and style. Along the way you will have to fight other Kabuki troops, garner the crowds favor to receive tips, and trade warriors with your defeated counterparts. You will need a very accomplished group of samurai when you arrive in Kyoto to defeat the city''s star troop.' FROM games WHERE igdb_id = 5873 ON CONFLICT (game_id, language_code) DO NOTHING;
