INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rayman vs Cullcut', 'Save Rayman from being a meal in this French typing-game. Rayman is trapped in a cage that is being lowered into a pit by the evil pirates! In order to stop this, the player needs to type words as fast as possible to save Rayman from being Cullcut''s dinner.' FROM games WHERE igdb_id = 61276 ON CONFLICT (game_id, language_code) DO NOTHING;
