INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tech-deck-skateboarding', 49995, '2001-04-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/yitblx0vrs4285xrv8k8.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tech Deck Skateboarding', 'Tech Deck Skateboarding challenges you to pull off the same tricks that regular skaters do just smaller. You play as the inimitable Thumb Guy, a lovable mascot who can pull off the fingerboard moves with the best of ''em. Featuring arcade-style play and animations, the game lets you whip out grinds, ollies, and flips with extreme flair. All of the licensed decks from real manufacturers are here, so you''ll be skating in style on your Tony Hawk deck. You''ll have access to a limited number of boards at the game''s outset, but as you get further and further along the road to glory you''ll be able to unlock more responsive outfits and other hidden goodies. With cool graphics, real decks, and totally original gameplay, it''s hardcore skating for hardcore fans!' FROM games WHERE igdb_id = 49995 ON CONFLICT (game_id, language_code) DO NOTHING;
