INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '90 Minutes: Sega Championship Football', 'Gameplay follows the norms of the genre - A to pass, B to throw a high lob, X to shoot, Y to change players, with the triggers to perform modifiers (though passes and lob shots) and sprint, although these can all be changed in the options. The player can also assign special tactics to each direction on the d-pad to adapt quickly according to the flow of the game.' FROM games WHERE igdb_id = 45802 ON CONFLICT (game_id, language_code) DO NOTHING;
