INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wizardry Chronicle', 'Wizardry Chronicle is a Japanese Wizardry spin-off. It is a role-playing game derivative of the original Wizardry games, with a menu town and a maze below to explore, monsters to defeat and items to be found. The game features five races, of which all but Humans are new: Sadeeq, Mirelli, Tairon and Wallbach. There are 15 different character classes, most of them familiar from other Wizardry games.' FROM games WHERE igdb_id = 172724 ON CONFLICT (game_id, language_code) DO NOTHING;
