INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magic: The Gathering', 'Magic: The Gathering is a Dreamcast game published and released by Sega in June 2001, though in Japan only. It takes place in the town of Magic Heart, the surrounding areas of Murg, Camat Island, Lydar Forest, Yeluk, Tornell, and The Balance Tower. It includes cards from 6th edition, Alliances, and Tempest. The game included 10 cards unique to it, generally utilizing random mechanics that would be difficult to implement in real-life card play.' FROM games WHERE igdb_id = 136558 ON CONFLICT (game_id, language_code) DO NOTHING;
