INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Powerpuff Girls: Mojo Jojo A-Go-Go', 'Blossom, Buttercup and Bubbles, are flying on the GameBoy Advance. It seems that Mojo Jojo has stolen the city''s jewels and has used them to power an army of cybernetic robots called "Mobots". With the Mobots unleashing a reign of terror on Townsville, it is up to The Powerpuff Girls to defeat Mojo Jojo and his minions and stop that bad little monkey from taking over Townsville!' FROM games WHERE igdb_id = 5888 ON CONFLICT (game_id, language_code) DO NOTHING;
