INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'E.T. the Extra Terrestrial: Digital Companion', 'E.T. The Extra-Terrestrial: Digital Companion is a game based on the classic 1982 film E.T. the Extra-Terrestrial. First, E.T. asks you many questions, like your first and last name, zip code, address, and favorite things. Then, a planner is set up that you can use daily. It includes a clock, a calendar, a clock, and a "To-Do List" where you can list tasks that need to be done. You can also print anything that needs to be remembered on the Game Boy Printer.' FROM games WHERE igdb_id = 278776 ON CONFLICT (game_id, language_code) DO NOTHING;
