INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('youre-under-arrest', 311062, '2001-03-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaoff.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4gda.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You''re Under Arrest', 'Taiho Shichau zo is a police-themed adventure base on the manga and anime with the same title. The player takes on a role of a 24-year old rookie police officer who just graduated. The game starts with you coming to your new place at work, and the moment you arrive, a small incident occurs and you get misunderstood for a thief. After situation gets resolved, you get introduced into your new place of work and meet your colleagues, among others the two heroines from manga and anime TV series, Natsumi Tsujimoto and Miyuki Kobayakawa. The game consists of two gameplay elements. Adventure mode which resembles a typical visual novel style with fully voiced dialogues for all but the main character, and animated portraits of characters currently speaking, as well as action choices during dialogues. Patrol mode features a patrol map of town where the player, along with Natsumi and Miyuki, is performing routine patrol work which may trigger an event scene or one of the mini-games. The points are also awarded for various different elements during patrol work.' FROM games WHERE igdb_id = 311062 ON CONFLICT (game_id, language_code) DO NOTHING;
