INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metropolismania', 'The best cities are built on friendship, not concrete! Everybody wants to live in the best city in the world! That''s why you''re a Metropolismaker, a well-connected urban planner who creates the most popular places on the planet. Of course com of your citizens have other ideas, so you''ll have to work extra hard to keep everyone happy.' FROM games WHERE igdb_id = 26661 ON CONFLICT (game_id, language_code) DO NOTHING;
