INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rageball', 'The futuristic sport of Rageball, inspired by Speedball 2, is fast, violent and deadly, and played by teams of exiled convicts who have nothing to lose. The year is 2612 and sports hit an all-time low. Therefore, prisoners are sent to the planet IS-326, nicknamed "The Hell", where they are forced to compete in a violent sport with no rules.
