INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Test Drive Off-Road Wide Open', 'Test Drive Off-Road ? Wide Open gives you brute force off-road racing through nature''s untamed badlands. Twelve kick-ass trucks fight for off-road supremacy in the wide open wilderness. Prove your skills in a Hummer, Dodge T-Rex, Ford Bronco, and more. Take towering jumps at high speeds in your unstoppable trucks. Grab your guts and hold on, because this one gets rough!' FROM games WHERE igdb_id = 6198 ON CONFLICT (game_id, language_code) DO NOTHING;
