INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lupin the 3rd: The Shooting', 'Players take the role of Lupin III as they shoot through fifteen of The Wolf''s wackiest endeavors. Driving scenarios where the player has to shoot left or right in order to control their vehicle appear as special levels. The game also offers a co-op mode where a second player can take up the role of Jigen and assist Lupin throughout the adventure.' FROM games WHERE igdb_id = 39594 ON CONFLICT (game_id, language_code) DO NOTHING;
