INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jumping Pop', 'Jumping Pop is a 2D arcade platform game with colorful graphics. Player is a monster hunter with a special, powerful vacuum cleaner - he needs to catch enemies (mummies, skeletons, cavemen, etc.) He can use a captured enemy as a missile to kill other opponents. After killing all the enemies the player goes to the next level.' FROM games WHERE igdb_id = 46798 ON CONFLICT (game_id, language_code) DO NOTHING;
