INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digimon Tamers: Digimon Medley', 'Digimon Medley is based on the popular manga and and anime series Digimon, in which ordinary Japanese children find a way into a digital world, where they help good digital monsters fight against evil ones. The game is not directly plot-related to Digimon Adventure or Digimon Tamers: Brave Tamer games. Instead, it follows more closely the actual episodes of the series.' FROM games WHERE igdb_id = 37551 ON CONFLICT (game_id, language_code) DO NOTHING;
