INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomberman Kart', 'Bomberman Kart is a racing game for PlayStation 2 starring the Bomberman characters. It is similar to Mario Kart. The game supports 4 player local multiplayer using the PlayStation 2 Multitap. The first version was released in 2001 in Japan and later 2003 in Europe. The second version, called Bomberman Kart DX (director''s cut) was released in 2004 only in Japan. Both versions have never been released in the United States.' FROM games WHERE igdb_id = 43535 ON CONFLICT (game_id, language_code) DO NOTHING;
