INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robopon 2 Ring Version', 'Hudson''s Pokemon-like handheld RPG for the Game Boy Color that featured the "GB Kiss", a built-in infrared port to make for wireless link, to trade Robopons with friends, interact with household remotes to power up or evolve your Robopon, and unlock treasure chests that can''t be opened otherwise.' FROM games WHERE igdb_id = 6560 ON CONFLICT (game_id, language_code) DO NOTHING;
