INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cubix-robots-for-everyone-race-n-robots', 49897, '2001-11-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/oq8b5eyintxemqcd4cdj.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cubix: Robots For Everyone - Race ''N Robots', 'Robots in everyday life? Believe it, folks. That''s the reality of the cool cartoon series, CUBIX: Robots for Everyone. The story follows the adventures of Connor a human boy and his robot, Cubix, through Bubble Town. Attempting to repair damaged robots and ward off evil beings, the pair encounters a whole cast of wacky characters every week. The game puts its emphasis on the racing aspects of the series, sending you to Bubble Town''s racing championship series. Your arch-nemesis, Dr. K, has a converted racer named Kolossal in the competition, and your goal is to earn the right to defeat it. Choose to race as any of your favorite series characters, including Hop2ix, Brutix, Don-Don, Diagnostix, and Cubix. You''ll be able to customize your racers to fit your liking, using elements like Grav-grip, Zero G, and other series-based power-ups to defy gravity and reach top speeds. Full of cool options game modes, and colorful graphics, Race N Robots is not to be missed.' FROM games WHERE igdb_id = 49897 ON CONFLICT (game_id, language_code) DO NOTHING;
